"use client";

// Generated by philote from component AuthorCard's actions. Do not edit.
import { useRouter } from "next/navigation";
import { useTransition } from "react";

import { toast } from "sonner";

import { remove } from "@/lib/actions/author-card";

import { Button } from "@/components/ui/button";

export default function AuthorCardActions({ id }: { id: string }) {
    const router = useRouter();
    const [pending, start] = useTransition();
    return (
        <div className="flex flex-wrap gap-2">
            <Button
                variant="destructive"
                size="sm"
                disabled={pending}
                onClick={() => {
                    if (!window.confirm("Delete this author?")) {
                        return;
                    }
                    start(async () => {
                        const error = await remove(id);
                        if (error) {
                            toast.error(error);
                        } else {
                            router.refresh();
                        }
                    });
                }}
            >
                {"Remove"}
            </Button>
        </div>
    );
}
